    'metadata.pegasus.txt · 支持 Android': ['metadata.pegasus.txt · 支持 Android', 'metadata.pegasus.txt · 支援 Android', 'metadata.pegasus.txt · Android 対応', 'metadata.pegasus.txt · Android support'],
